// =====================================================================
// GAME LOGIC
// =====================================================================
// =====================================================================
// 1. Rules recovered from the original game
// =====================================================================
// Native float stores round to 32 bits.
const nativeFloat = Math.fround;
const BASE_SCORE = Object.freeze({
  tank: 100,
  h6tank: 500,
  jeep: 2000
});
const NATIVE_STEP = 0.05; // EAGLView drawView 0x3fba–0x4002: elapsed*100 >= 5
function initNativeCapabilities() {
  return [{
    fireDelay: 0,
    turnStep: nativeFloat(0.04),
    maxSpeed: nativeFloat(0.075),
    acceleration: nativeFloat(0.004),
    drag: nativeFloat(0.98),
    projectileSpeed: 0
  }, {
    fireDelay: 150,
    turnStep: nativeFloat(0.02),
    maxSpeed: nativeFloat(0.06),
    acceleration: nativeFloat(0.002),
    drag: nativeFloat(0.96),
    projectileSpeed: nativeFloat(0.2)
  }, {
    fireDelay: 200,
    turnStep: nativeFloat(0.01),
    maxSpeed: nativeFloat(0.08),
    acceleration: nativeFloat(0.001),
    drag: nativeFloat(0.98),
    projectileSpeed: nativeFloat(0.3)
  }];
}
class GameRules {
  constructor() {
    this.startGame();
  }
  startGame() {
    this.score = 0;
    this.level = 0;
    this.divider = 0;
    this.nextTankTimer = 20;
    this.vehicles = initNativeCapabilities();
    this.bonusAmount = 0;
    this.bonusTimer = 0;
    this.bonusReason = 0;
    this.flash = 0;
    this.startLife();
  }
  startLife() {
    this.multiplier = 1;
  }
  increaseSkill() {
    this.level++;
    if (this.level <= 5) {
      this.vehicles[0].maxSpeed = Math.min(nativeFloat(this.vehicles[0].maxSpeed * 1.1),
        nativeFloat(0.165));
      for (let i = 1; i < 3; i++) {
        const v = this.vehicles[i];
        v.fireDelay = Math.max(18, Math.trunc(v.fireDelay * 0.74));
        v.turnStep = nativeFloat(v.turnStep * 1.1);
        v.maxSpeed = nativeFloat(v.maxSpeed * 1.1);
        v.projectileSpeed = nativeFloat(v.projectileSpeed * 1.1);
      }
    }
    this.nextTankTimer = Math.max(2, this.nextTankTimer - 5);
  }
  destroyed() {
    if (++this.divider > 3) {
      this.divider = 0;
      this.increaseSkill();
    }
  }
  crushed() {
    if(++this.divider>8){this.divider=0;this.increaseSkill();}
  }
  award(points) {
    this.score = (this.score + points) >>> 0;
  }
  projectileHit(name, age) {
    if (age > 55) {
      this.multiplier = Math.min(5, this.multiplier + 1);
      this.flash = 100;
    }
    this.award(BASE_SCORE[name] * this.multiplier);
    this.destroyed();
  }
  nukeHit(name) {
    this.award(BASE_SCORE[name] * this.multiplier);
    this.destroyed();
  }
  finishNuke(kills) {
    if (kills > 1) {
      this.bonusAmount = kills * 5000;
      this.award(this.bonusAmount);
      this.bonusTimer = 100;
      this.bonusReason = 1;
      return this.bonusAmount;
    }
    return 0;
  }
  tick() {
    if (this.flash > 0) this.flash--;
    if (this.bonusTimer > 0) this.bonusTimer--;
  }
}

function collectPowerup(t, kind) {
  if (kind === 'RapidFire') t.rapidFire += 500;
  if (kind === 'Nuke') {
    t.rapidFire = 0;
    t.nukes = 500;
    t.reload = 0;
  }
  if (kind === 'Shields') t.shields += 1000;
}

function tickPowerups(t) {
  if (t.rapidFire > 0) t.rapidFire--;
  if (t.nukes > 0) t.rapidFire = 0;
  if (t.shields > 0) t.shields--;
}

function projectileLimit(scale) {
  return scale < 5 ? 60 : 200;
}
function projectileVelocity(yaw, rapid = false, speed = null) {
  const c = nativeFloat(nativeFloat(Math.cos(nativeFloat(yaw))) * 57.29577951308232);
  const s = nativeFloat(nativeFloat(Math.sin(nativeFloat(yaw))) * 57.29577951308232);
  const v = speed === null ? nativeFloat(rapid ? 0.4 : 0.22) : nativeFloat(speed);
  return {
    x: -nativeFloat(nativeFloat(c * 0) - nativeFloat(v * s)),
    z: nativeFloat(nativeFloat(s * 0) + nativeFloat(v * c))
  };
}

function reloadFrames(rapid) {
  return rapid ? 1 : 120;
}

// Native 0x1cd0c–0x1ce20: randomized muzzle position, unchanged shot heading.
function rapidMuzzle(x, y, z, yaw, side, r1, r2) {
  const f = Math.fround;
  const angle = f(f(f(yaw) - f(Math.PI / 2)) + f(f(f(r1) - f(0.5)) * f(Math.PI * 2)));
  const c = f(f(Math.cos(angle)) * 57.29577951308232);
  const s = f(f(Math.sin(angle)) * 57.29577951308232);
  const offset = f(f(side) * f(0.6));
  return [f(f(x) - f(f(c * 0) - f(s * offset))),
    f(f(f(f(y) + 30) + 7) + f(f(f(r2) * 20) - 10)),
    f(f(f(s * 0) + f(c * offset)) + f(z))];
}

// END NATIVE RULES

// Replace rounded legacy assets with full-precision native constructor output.
Object.assign(MODELS, NATIVE_LEGACY_MODELS);

// =====================================================================
// VECTOR TANKS - browser reconstruction of the iOS game (v1.4)
// by Peter Hirschberg, reverse-engineered from the original ARM binary.
//
// All wireframe geometry, part scales, colors and placement constants
// were extracted by executing the original C++ builder functions in a
// Thumb-2 interpreter and dumping the object3d data (models.js).
//
// Transform pipeline (matches object3d::Transform() in the original):
//   world = R_group(yaw) . (local_vertex * part_scale) + group_position
// The original stores positions as (y, x, z) and scales as (sy, sx, sz);
// models.js already normalizes both to [x, y, z] / [sx, sy, sz].
//
// Colors: colorType is four doubles [alpha,r,g,b] + float width/glow; a
// single wire color and single fill color per object (verified in
// DrawObjectWires / DrawObjectFills).
//
// Native numerical rules and submission order are tested against the ARM
// reference. Platform adapters and remaining limits are recorded in PORT.md.
//
// Controls:  W/S drive   A/D turn hull   click / space fire along the sight
//            N nuke      P pause         M mute
// =====================================================================

// ------------------------------------------------ tuning constants
const TUNE = {
  cameraHeight: 29.5, // extracted: player tank rides at y=29.5
};

// ------------------------------------------------ vector renderer
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = () => canvas.width,
  H = () => canvas.height;

// glEnable2D 0x56bc: portrait glOrthof(0,600,800,0,-1,1).
// Landscape drawing space is 800×600; original display/touch space 480×320.
const NATIVE_SCREEN = Object.freeze({drawWidth:800, drawHeight:600, width:480, height:320});
function fitNativeScreen(width, height) {
  const scale = Math.min(width / NATIVE_SCREEN.width, height / NATIVE_SCREEN.height);
  const w = Math.max(1, Math.round(NATIVE_SCREEN.width * scale));
  const h = Math.max(1, Math.round(NATIVE_SCREEN.height * scale));
  return {width:w, height:h, left:(width-w)/2, top:(height-h)/2};
}

// safe-area insets (notch) + orientation support
const SAFE = {
  left: 0,
  right: 0,
  top: 0,
  bottom: 0
};

function sideStickMode() {
  return window.innerWidth>window.innerHeight && ('ontouchstart' in window || navigator.maxTouchPoints>0);
}
function browserScreenFrame() {
  if(!sideStickMode())return fitNativeScreen(window.innerWidth,window.innerHeight);
  const rail=Math.min(144,Math.max(78,window.innerHeight*.24));
  const available=Math.max(1,window.innerWidth-SAFE.left-SAFE.right-rail*2);
  const frame=fitNativeScreen(available,window.innerHeight);
  frame.left+=(window.innerWidth-available+SAFE.left-SAFE.right)/2;
  return frame;
}
function resize() {
  // read the notch insets from the CSS env() probe
  try {
    const cs = getComputedStyle(document.getElementById('safeProbe'));
    SAFE.top = parseFloat(cs.paddingTop) || 0;
    SAFE.bottom = parseFloat(cs.paddingBottom) || 0;
    SAFE.left = parseFloat(cs.paddingLeft) || 0;
    SAFE.right = parseFloat(cs.paddingRight) || 0;
  } catch (e) {
    /* probe unavailable */ }
  // Browser adapter: fit the original display proportions into any window.
  const frame = browserScreenFrame();
  const w = frame.width, h = frame.height;
  canvas.width = w;
  canvas.height = h;
  canvas.style.position = 'fixed';
  canvas.style.left = frame.left + 'px';
  canvas.style.width = w + 'px';
  canvas.style.height = h + 'px';
  canvas.style.top = frame.top + 'px';
  canvas.style.transform = 'none';
  layoutSideSticks();
  updateOrientationUI();
}

function layoutSideSticks() {
  const frame=browserScreenFrame(),trackW=Math.min(144,frame.height*.195),trackH=frame.height*.76;
  for(const [id,x] of [['leftStick',(SAFE.left+frame.left-trackW)/2],
    ['rightStick',(frame.left+frame.width+window.innerWidth-SAFE.right-trackW)/2]]) {
    const el=document.getElementById(id);
    Object.assign(el.style,{left:x+'px',top:(frame.top+frame.height*.12)+'px',width:trackW+'px',height:trackH+'px'});
  }
}
function drawSideSticks() {
  document.getElementById('sideSticks').style.display=sideStickMode()&&state===STATE.PLAYING?'block':'none';
  for(const [id,value] of [['leftStick',touchDrive.left],['rightStick',touchDrive.right]]) {
    document.getElementById(id).firstElementChild.style.top=((1-value)/3*100)+'%';
  }
}

function updateOrientationUI() {
  const el = document.getElementById('rotateOverlay');
  if (!el) return;
  const touch = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
  const portrait = window.innerHeight > window.innerWidth;
  el.style.display = touch && portrait ? 'block' : 'none';
  // keep the message banner inside the letterbox band
  const hud = document.getElementById('hudMsg');
  if (hud) {
    const bandTop = Math.max(0, (window.innerHeight - canvas.height) / 2);
    hud.style.top = (bandTop + canvas.height * 0.16) + 'px';
  }
}
window.addEventListener('resize', resize);
window.addEventListener('orientationchange', () => setTimeout(resize, 250));
resize();

// best effort: enter fullscreen and lock landscape on the first touch
// (mobile browsers only allow this from a user gesture)
let lockTried = false;
window.addEventListener('touchstart', function firstTouch() {
  if (lockTried) return;
  lockTried = true;
  try {
    const el = document.documentElement;
    const req = el.requestFullscreen || el.webkitRequestFullscreen;
    if (req) {
      Promise.resolve(req.call(el)).then(() => {
        if (screen.orientation && screen.orientation.lock) {
          screen.orientation.lock('landscape').catch(() => {});
        }
      }).catch(() => {});
    }
  } catch (e) {
    /* not supported - the rotate prompt covers it */ }
}, {
  once: true,
  passive: true
});

// camera space -> screen (mirrors matrix3d::ProjectVertex)
function project(v, cam, out) {
  const cy = Math.cos(cam.yaw),
    sy = Math.sin(cam.yaw);
  const cp = Math.cos(cam.pitch),
    sp = Math.sin(cam.pitch);
  const dx = v[0] - cam.x,
    dy = v[1] - cam.y,
    dz = v[2] - cam.z;
  const x1 = dx * cy + dz * sy;
  const z1 = -dx * sy + dz * cy;
  const y2 = dy * cp - z1 * sp;
  const z2 = dy * sp + z1 * cp;
  if (z2 <= 0.001) {
    out.ok = false;
    return;
  }
  const cr=Math.cos(cam.roll||0),sr=Math.sin(cam.roll||0);
  const projected = nativeProjectVertex(x1*cr+y2*sr,-x1*sr+y2*cr,z2);
  out.ok = true;
  // graphicsOrigin=(300,400), portrait 600×800, rotated to landscape.
  out.x = W() / 2 + projected[0] * W() / NATIVE_SCREEN.drawWidth;
  out.y = H() / 2 - projected[1] * H() / NATIVE_SCREEN.drawHeight;
  out.z = z2;
  out.scale = (320 * H() / NATIVE_SCREEN.drawHeight) / Math.fround(z2); // pixels per world unit
}

const P1 = {
    ok: false
  },
  P2 = {
    ok: false
  };

// apply scale -> yaw rotation -> translation; stores result in obj._tv
function transformObj(obj, pos, rot, extraYaw) {
  if (!obj._tv) obj._tv = obj.v.map(() => [0, 0, 0]);
  const yaw = (rot ? rot[0] : 0) + (extraYaw || 0);
  const pitch = rot ? rot[1] : 0;
  const roll = rot ? rot[2] : 0;
  const cy = Math.cos(yaw),
    sy = Math.sin(yaw);
  const cp = Math.cos(pitch),
    sp = Math.sin(pitch);
  const cr = Math.cos(roll),
    sr = Math.sin(roll);
  const sx = obj.sc[0],
    sy2 = obj.sc[1],
    sz = obj.sc[2];
  for (let i = 0; i < obj.v.length; i++) {
    // scale first (local, unit-sized geometry)
    let x = obj.v[i][0] * sx,
      y = obj.v[i][1] * sy2,
      z = obj.v[i][2] * sz;
    // Native matrix3d::Rotate applies yaw, pitch, then roll. Swapping
    // native (vertical,horizontal,z) into (x,y,z) reverses pitch/roll signs.
    const x1 = x * cy - z * sy, z1 = x * sy + z * cy;
    const y2 = y * cp + z1 * sp, z2 = -y * sp + z1 * cp;
    const x3 = x1 * cr + y2 * sr, y3 = -x1 * sr + y2 * cr;
    obj._tv[i][0] = x3 + pos[0];
    obj._tv[i][1] = y3 + pos[1];
    obj._tv[i][2] = z2 + pos[2];
  }
}

// Native colorType: four doubles [alpha, red, green, blue], then
// float line width and float glow. initGame 0x17a38–0x17aaa.
const NATIVE_PALETTE = Object.freeze({
  obstacleWire: [0.3, 1, 0.4, 0.4, 2, 1.5],
  obstacleFill: [0.16, 1, 0.2, 0.2, 0, 0],
  logoWire: [0.4, 0, 1, 0, 3, 0],
});
function colorTypeStyle(c) {
  if (!c || c[0] <= 0 || !(c[1] || c[2] || c[3])) return null;
  return `rgba(${Math.trunc(Math.fround(c[1])*255)},${Math.trunc(Math.fround(c[2])*255)},${Math.trunc(Math.fround(c[3])*255)},${c[0]})`;
}

// Outlines executed from original AlphanumericsPrint/drawText, not a system font.
function vectorText(text,x,y) {
  text=String(text).toUpperCase();
  const pixels=Number(/([0-9.]+)px/.exec(String(ctx.font))?.[1]||14);
  const size=pixels/2,advance=size*1.8;
  let cursor=ctx.textAlign==='center'?x-(text.length-1)*advance/2:
    ctx.textAlign==='right'?x-(text.length-1)*advance-size*.65:x+size*.65;
  ctx.save();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=1;ctx.beginPath();
  for(const char of text){
    for(const v of NATIVE_GLYPHS[char]||[]){ctx.moveTo(cursor+v[0]*size,y-(v[1]+1)*size);ctx.lineTo(cursor+v[2]*size,y-(v[3]+1)*size);}
    cursor+=advance;
  }
  ctx.stroke();ctx.restore();
}

function drawNativeCracks() {
  const vectors=NATIVE_CRACK_VECTORS.slice(0,nativeCracksStep);
  ctx.save();ctx.shadowBlur=0;
  for(const pass of ['glow','core']){
    ctx.lineWidth=pass==='glow'?8:1;
    for(const v of vectors){
      const rgba=nativeVectorColor(v.color,0,0)[pass];if(!rgba)continue;
      ctx.strokeStyle=`rgba(${rgba[0]},${rgba[1]},${rgba[2]},${rgba[3]/255})`;
      ctx.beginPath();ctx.moveTo(W()/2+v.from[1]*W()/800,H()/2-v.from[0]*H()/600);
      ctx.lineTo(W()/2+v.to[1]*W()/800,H()/2-v.to[0]*H()/600);ctx.stroke();
    }
  }
  ctx.restore();
}

// ProjectVertex 0x6c7e: only the divisor is rounded to Float32.
function nativeProjectVertex(x, y, z) {
  const divisor = Math.fround(z) || Math.fround(0.00001);
  return [x * 320 / divisor, y * 320 / divisor, z];
}

// vlAddVector 0x4f24–0x526a. Option 0 is the normal intensity setting.
// Keep Float32 stores and byte truncation: native OpenGL takes RGBA bytes.
function nativeVectorColor(c, fromDepth, toDepth, intensity = 0) {
  const f = Math.fround;
  const a = f(c[0]);
  let ceiling = f(a + a);
  if (intensity === 1) ceiling = f(ceiling + ceiling);
  else if (intensity === 2) ceiling = f(ceiling * 3);
  else if (intensity === 3) ceiling = f(ceiling * 6);
  const depth = f((fromDepth + toDepth) * 0.5);
  const fade = f(f(depth / -1200) + 1);
  const core = f(Math.max(0, Math.min(ceiling, f(f(ceiling + ceiling) * fade))));
  const glowBase = f(Math.max(0, Math.min(a, f(fade * (c[0] + c[0])))));
  let glow = f(f(glowBase * 0.15) * (c[5] || 0));
  glow = f(glow + glow);
  if (intensity === 1) glow = f(glow * 1.25);
  else if (intensity === 2) glow = f(glow * 1.5);
  else if (intensity === 3) glow = f(glow * 1.75);
  const rgb = c.slice(1, 4).map(v => Math.trunc(f(f(v) * 255)) & 255);
  const bytes = alpha => [...rgb, Math.trunc(f(Math.min(1, alpha) * 255)) & 255];
  return {core: core > 0 ? bytes(core) : null,
    glow: core > 0 && fromDepth <= 1000 && toDepth <= 1000 && glow > 0 ? bytes(glow) : null};
}

// GenerateLineList 0x2cd0: deduplicate consecutive edges, then append the
// closing edge for filled polygons (native preserves those duplicates).
function nativeLineList(polygons, fillAlpha = 0) {
  const seen = new Set(), lines = [];
  for (const poly of polygons) {
    if (poly.length < 2) continue;
    for (let i = 0; i < poly.length-1; i++) {
      const a = poly[i], b = poly[i+1];
      const key = Math.min(a,b) + ':' + Math.max(a,b);
      if (!seen.has(key)) { seen.add(key); lines.push([a,b]); }
    }
    if (fillAlpha > 0 && poly.at(-1) !== poly[0]) {
      const a=poly.at(-1), b=poly[0];
      lines.push([a,b]); seen.add(Math.min(a,b)+":"+Math.max(a,b));
    }
  }
  return lines;
}

function nativeFillAlpha(alpha, depths) {
  const f=Math.fround;
  const average=f(depths.reduce((sum,z)=>f(sum+z),0)/depths.length);
  return f(Math.min(alpha, alpha*2*f(f(average/-1200)+1)));
}
// Fills submit immediately; wires share the native vector list. vlAddVector
// 0x4eda–0x4ef4 flushes when its Float32-coordinate count exceeds 987.
let sceneVectors = null;
function queueSceneVectors(segments){
  for(const segment of segments){
    if(sceneVectors.length>=165){flushSceneVectors();sceneVectors=[];}
    sceneVectors.push(segment);
  }
}
function flushSceneVectors() {
  const segments=sceneVectors;sceneVectors=null;
  if(!segments)return;
  ctx.save();ctx.shadowBlur=0;ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
  for(const pass of ['glow','core']){
    ctx.lineWidth=pass==='glow'?8:1;
    for(const {p,q,color} of segments){
      const c=color[pass];if(!c)continue;
      ctx.strokeStyle=`rgba(${c[0]},${c[1]},${c[2]},${c[3]/255})`;
      ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();
    }
  }
  ctx.restore();
}
function drawObj(obj, pos, rot, extraYaw, maxDepth = Infinity) {
  transformObj(obj, pos, rot, extraYaw);
  const points = obj._tv.map(v => { const p = {}; project(v, cam, p); return p; });
  const fill = colorTypeStyle(obj.f);
  ctx.save();
  // _vlRenderVectorList uses SRC_ALPHA, ONE_MINUS_SRC_ALPHA, not additive blending.
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = 1;
  ctx.shadowBlur = 0;
  if (fill) {
    // 0x4b74–0x4b88 carries the faded alpha into the next face of this object.
    let faceAlpha=obj.f[0];
    for (const poly of obj.p) {
      if (poly.length < 3 || poly.some(i => !points[i].ok)) continue;
      // DrawObjectFills 0x4b02–0x4b7e: fade averaged Float32 depth.
      const alpha = faceAlpha = nativeFillAlpha(faceAlpha, poly.map(i=>points[i].z));
      if (!(alpha > 0)) continue;
      ctx.fillStyle = colorTypeStyle([alpha,...obj.f.slice(1)]);
      ctx.beginPath();
      poly.forEach((i,k) => k ? ctx.lineTo(points[i].x, points[i].y) : ctx.moveTo(points[i].x, points[i].y));
      ctx.closePath(); ctx.fill();
    }
  }
  if (obj._linePolygons !== obj.p) {
    obj._linePolygons = obj.p; obj._lines = nativeLineList(obj.p, obj.f[0]);
  }
  const segments = [];
  for (const [a,b] of obj._lines) {
    const p = points[a], q = points[b];
    // 0x5492–0x54fc accepts a wire only when at least one horizontal
    // endpoint lies inside the native -400..400 drawing bounds.
    if(!((p.x>=0&&p.x<=W())||(q.x>=0&&q.x<=W())))continue;
    // DrawObjectWires 0x54fe–0x5548 requires both endpoints in 0.001..1200.
    if (!p.ok || !q.ok || p.z <= 0.001 || q.z <= 0.001 || p.z >= 1200 || q.z >= 1200 || Math.min(p.z,q.z) > maxDepth) continue;
    const color = nativeVectorColor(obj.w, p.z, q.z);
    if (color.core) segments.push({p,q,color});
  }
  if(sceneVectors){queueSceneVectors(segments);ctx.restore();return;}
  // Native submits all 8px glow lines, then all 1px core lines (0x4dc0, 0x4df8).
  for (const pass of ['glow','core']) {
    ctx.lineWidth = pass === 'glow' ? 8 : 1;
    for (const {p,q,color} of segments) {
      const c = color[pass]; if (!c) continue;
      ctx.strokeStyle = `rgba(${c[0]},${c[1]},${c[2]},${c[3]/255})`;
      ctx.beginPath(); ctx.moveTo(p.x,p.y); ctx.lineTo(q.x,q.y); ctx.stroke();
    }
  }
  ctx.restore();
}
function cameraDepth(v) {
  const dx = v[0] - cam.x, dz = v[2] - cam.z;
  return (v[1]-cam.y)*Math.sin(cam.pitch) + (-dx*Math.sin(cam.yaw)+dz*Math.cos(cam.yaw))*Math.cos(cam.pitch);
}

// DrawObjectList 0x6e4c–0x6e92: ground distance 1400, bearing within 60°.
function nativeObjectVisible(pos) {
  const distance=NativeWorld.distance(player.x,player.z,pos[0],pos[2]);
  if(distance>1400)return false;
  const bearing=Math.atan2(-(pos[0]-player.x),pos[2]-player.z);
  return Math.abs(normAngle(bearing-cam.yaw))*180/Math.PI<=60;
}

function makeEntity(m) {
  return {
    v: m.v,
    p: m.p,
    w: m.w,
    f: m.f,
    sc: [...m.sc],
    pos: [...m.pos],
    rot: m.rot ? [...m.rot] : [0, 0, 0]
  };
}

function makePowerup(kind, pos) {
  const o = makeEntity(NATIVE_POWERUP_MODELS[kind]);
  o.kind = kind;
  o.pos = [...pos];
  o.spin = 0;
  // User/video reference: rapid fire purple, shield/nuke yellow.
  // Keep native alpha, line width, glow and fill opacity.
  const rgb = kind === 'RapidFire' ? [1, 0, 1] : [1, 1, 0];
  o.w = [...o.w]; o.f = [...o.f];
  o.w.splice(1, 3, ...rgb); o.f.splice(1, 3, ...rgb);
  return o;
}

// External MP3 audio. AudioContext is created/resumed only by a user gesture.
const AudioSys = {
  ctx: null,
  master: null,
  buffers: {},
  bytes: {},
  fetches: {},
  muted: false,
  loading: null,
  preloading: null,
  url(name) {
    if (SOUND_URLS[name]) return SOUND_URLS[name];
    const base = SOUND_BASE_URL.trim();
    return base ? base.replace(/\/?$/, '/') + encodeURIComponent(SOUND_FILES[name])
      : new URL('sounds/' + encodeURIComponent(SOUND_FILES[name]), document.baseURI).href;
  },
  fetchSound(name) {
    if (!SOUND_FILES[name]) return Promise.reject(new Error('Unknown sound: '+name));
    if (this.bytes[name]) return Promise.resolve(this.bytes[name]);
    if (this.fetches[name]) return this.fetches[name];
    this.fetches[name] = fetch(this.url(name), {mode:'cors', credentials:'omit'})
      .then(response => {
        if (!response.ok) throw new Error('Audio HTTP '+response.status+': '+name);
        return response.arrayBuffer();
      })
      .then(bytes => (this.bytes[name] = bytes))
      .finally(() => { delete this.fetches[name]; });
    return this.fetches[name];
  },
  preload() {
    if (!this.preloading) {
      this.preloading = Promise.all(Object.keys(SOUND_FILES).map(name =>
        this.fetchSound(name).then(() => true, () => false)
      )).then(results => {
        const missing=results.filter(ok=>!ok).length;
        if(missing)console.warn('Vector Tanks: '+missing+' external audio files unavailable. Check SOUND_BASE_URL / SOUND_URLS and CORS. The game can still play.');
      });
    }
    return this.preloading;
  },
  init() {
    try {
      if (!this.ctx || this.ctx.state === 'closed') {
        const Context=window.AudioContext || window.webkitAudioContext;
        if(!Context)return;
        this.ctx=new Context();
        this.master=this.ctx.createGain();
        this.master.gain.value=this.muted?0:0.5;
        this.master.connect(this.ctx.destination);
        this.loading=null;
        this.unlocked=false;
      }
      // Keep resume() and the silent unlock source inside this gesture stack.
      if(this.ctx.state!=='running')Promise.resolve(this.ctx.resume()).catch(()=>{});
      if(!this.unlocked || this.ctx.state!=='running') {
        if(typeof this.ctx.createBuffer==='function') {
          const source=this.ctx.createBufferSource();
          source.buffer=this.ctx.createBuffer(1,1,this.ctx.sampleRate||44100);
          source.connect(this.master);source.start(0);
        }
        this.unlocked=true;
      }
      if(!this.loading)this.loading=this.loadAll(Object.keys(SOUND_FILES)).catch(error=>console.warn('Vector Tanks audio:',error.message));
    } catch(error) {
      console.warn('Vector Tanks audio:',error.message);
    }
  },
  async load(name) {
    if(this.buffers[name] || !this.ctx)return;
    const bytes=await this.fetchSound(name);
    this.buffers[name]=await this.ctx.decodeAudioData(bytes.slice(0));
  },
  async loadAll(names) {
    await this.preload();
    const results=await Promise.all(names.map(name => this.load(name).then(()=>true,()=>false)));
    return results.every(Boolean);
  },
  play(name, vol = 1, rate = 1, loop = false) {
    if (this.muted || !this.ctx || this.ctx.state!=='running' || !this.buffers[name])return null;
    const source=this.ctx.createBufferSource();
    source.buffer=this.buffers[name];source.playbackRate.value=rate;
    const gain=this.ctx.createGain();gain.gain.value=vol;
    source.connect(gain);gain.connect(this.master);
    if(loop)source.loop=true;
    source.start();return source;
  }
};

