// ------------------------------------------------ test / debug hooks
// window.render_game_to_text() returns a compact JSON game state so the
// automated Playwright QA loop can verify the game without visuals.
// window.advanceTime(ms) steps the simulation deterministically.
window.render_game_to_text = function() {
  return JSON.stringify({
    mode: ['ATTRACT', 'PLAYING', 'DEAD', 'GAMEOVER'][state],
    // coordinates: origin at world center, x east, y up, z north (heading 0 = +z)
    player: {
      x: Math.round(player.x),
      z: Math.round(player.z),
      yaw: +player.yaw.toFixed(2),
      turret: +player.turret.toFixed(2),
      alive: player.alive
    },
    enemies: enemies.map((e) => ({
      x: Math.round(e.x),
      z: Math.round(e.z),
      hp: e.hp,
      type: e.type.name
    })),
    shells: shells.length,
    powerups: world.powerups.map((p) => ({
      kind: p.kind,
      x: Math.round(p.pos[0]),
      z: Math.round(p.pos[2])
    })),
    score,
    lives,
    wave,
    multiplier: native.multiplier,
    skillLevel: native.level,
  });
};
window.advanceTime = function(ms) {
  const steps = Math.max(1, Math.round(ms / (1000 / 60)));
  for (let i = 0; i < steps; i++) {
    const dt = 1 / 60;
    lastTime = performance.now();
    if (!paused) advanceSimulation(dt);
    render(dt);
  }
};
window.simulateInput = function(keysObj, mouse) {
  for (const k in keysObj) keys[k] = keysObj[k];
  if (mouse) {
    if ('x' in mouse) mouseX = mouse.x;
    if ('y' in mouse) mouseY = mouse.y;
    if ('down' in mouse) mouseDown = mouse.down;
  }
};

// FPS overlay (game QA requirement; remove for a clean build)
const _dbg = {
  frames: 0,
  last: performance.now(),
  fps: 0,
  ft: 0,
  prev: 0
};

function drawDebug() {
  _dbg.frames++;
  const n = performance.now();
  _dbg.ft = n - (_dbg.prev || n);
  _dbg.prev = n;
  if (n - _dbg.last >= 1000) {
    _dbg.fps = (_dbg.frames * 1000) / (n - _dbg.last);
    _dbg.frames = 0;
    _dbg.last = n;
  }
  ctx.save();
  ctx.fillStyle = 'rgba(0,0,0,.7)';
  ctx.fillRect(0, 0, 170, 36);
  ctx.font = '11px monospace';
  ctx.fillStyle = _dbg.fps < 30 ? '#f66' : '#6f6';
  ctx.textBaseline = 'top';
  vectorText(`FPS:${_dbg.fps.toFixed(0)} ${_dbg.ft.toFixed(1)}ms`, 6, 16);
  ctx.fillStyle = '#6f6';
  vectorText(`objs:${enemies.length} sh:${shells.length}`, 6, 30);
  ctx.restore();
}

