// Native draw-time toggles are latched at the 50ms draw cadence, so a 120Hz
// browser does not make pickups, mines or HUD labels blink six times faster.
const hudVisual={dim:false,pickup:false,mine:true,mineTimer:0,
  dotted:0,ready:{on:false,timer:4},
  reload:{on:false,timer:8},nuke:{on:false,timer:6},blocked:{on:false,timer:4}};
function nativeBlink(s,on,off){if(--s.timer<=0){s.on=!s.on;s.timer=s.on?on:off;}}
function stepNativeVisuals(){
  for(let i=0;i<starTwinkles.length;i++)starTwinkles[i]=Math.random();
  hudVisual.dim=!hudVisual.dim;
  for(const p of world.powerups)p.w[0]=hudVisual.pickup?1:.8;
  hudVisual.pickup=!hudVisual.pickup;
  for(const o of world.obstacles)if(o.type===9){
    const polygons=NATIVE_OBSTACLE_MODELS[9].p;
    o.p=hudVisual.mine?polygons:polygons.slice(0,1);
  }
  if(++hudVisual.mineTimer>5){hudVisual.mineTimer=0;hudVisual.mine=!hudVisual.mine;}
  if(player.reloading){hudVisual.dotted=0;nativeBlink(hudVisual.reload,8,3);}
  else if(player.rapidFire<=0){
    if(player.nukes>0)nativeBlink(hudVisual.nuke,6,2);
    if(hudVisual.dotted<=169)hudVisual.dotted+=15;
    if(hudVisual.dotted>=168)nativeBlink(hudVisual.ready,4,1);
  }
  if(player.movementBlocked)nativeBlink(hudVisual.blocked,4,4);
}
