// ------------------------------------------------ world construction
// Arena facts extracted from the binary: terrain tiles are 1778 apart and
// 1800 units in scale; the player tank rides at y=29.5.
const TERRAIN_GRID = 1778;

const world = {
  obstacles: [],
  powerups: [],
  terrain: [],
  logo: []
};

function buildWorld() {
  // Preserve every native terrain polygon; GenerateLineList removes shared edges.
  world.terrain = MODELS.terrain.map((m) => {
    const o = makeEntity(m);
    o.p = m.p;
    return o;
  });
  // initGame 0x17abc–0x17c18: 40 objects; first ten are type 9,
  // remaining types chosen by randFromTo(1,3). Native constructors and scales
  // are dumped in native-obstacles.js; no invented cube/pyramid meshes.
  const rng = mulberry32(1234); // Browser RNG adapter; not Darwin libc rand.
  const randomFloat = () => nativeFloat(rng());
  world.obstacles = Array.from({length:40}, (_,i) => {
    const type = i < 10 ? 9 : Math.trunc(nativeFloat(nativeFloat(randomFloat()*3)+1));
    const o = makeEntity(NATIVE_OBSTACLE_MODELS[type]);
    o.type = type;
    o.blocking = NativeWorld.playerBlocking(type);
    o.enabled = true;
    o.rot = [i < 10 ? 0 : nativeFloat(randomFloat()*360)*Math.PI/180,0,0];
    o.pos[1] = nativeFloat((o.sc[1]-1)*0.5); // placeObjectOnGround 0x124dc
    return o;
  });
  // PositionObstacles 0x15af8: ±2000 around player; reject distances <400.
  const place = o => {
    o.pos[0] = player.x + nativeFloat(nativeFloat(randomFloat()*4000)-2000);
    o.pos[2] = player.z + nativeFloat(nativeFloat(randomFloat()*4000)-2000);
  };
  world.obstacles.forEach(place);
  let moved;
  do {
    moved = false;
    for (let i=0;i<40;i++) for (let j=0;j<40;j++) {
      if (i===j) continue;
      const o=world.obstacles[i], q=world.obstacles[j];
      if (Math.hypot(o.pos[0]-q.pos[0],o.pos[2]-q.pos[2])<400 || Math.hypot(o.pos[0]-player.x,o.pos[2]-player.z)<400) {
        place(o); moved=true;
      }
    }
  } while (moved);
  // initGame: three nukes, eight shields, nine rapid-fire pickups.
  world.powerups = Array.from({length:20},(_,i)=>makePowerup(i<3?'Nuke':i<11?'Shields':'RapidFire',[0,19.5,0]));
  NativeWorld.positionPickups(world.powerups,world.obstacles,player,()=>rng());
  // The horizon ridge is NOT a 3D object: drawBackground() draws it as a
  // screen-space band from the C.100 constant (see drawMountains below).
  // logo for the attract screen: the video shows SINGLE FLAT OUTLINES -
  // planar letters lying on the ground, no extrusion / z depth
  const logoMesh = MODELS.logo.find((m) => m.v.length > 20) || MODELS.logo[0];
  world.logo = [makeEntity(logoMesh)];
}

